#!/usr/bin/env python3
"""Round 90b tiles (27 September): the map's own layers in place of Global Safety Net's, built from the original data
(human_modification, wilderness, critical_habitat, reforestation, mangroves), Potapov et al.'s cropland (cropland_expansion),
their shared helper (scripts/lib/pyramid.py), and the Atlas's city maps placed at their printed scale (atlas_city_plates).
Upload to the culprits-tiles-more repo's patches folder. Safe to run twice: each file is written only if it differs."""
import base64, os, pathlib, sys
FILES = {
    'scripts/lib/pyramid.py': """""",
    'scripts/human_modification.py': """""",
    'scripts/reforestation.py': """""",
    'scripts/wilderness.py': """""",
    'scripts/critical_habitat.py': """""",
    'scripts/mangroves.py': """""",
    'scripts/cropland_expansion.py': """""",
    'scripts/atlas_city_plates.py': """""",
}
if not os.path.isdir("scripts"):
    sys.exit("Run this from the culprits-tiles-more folder.")
changed = 0
for name, b64 in FILES.items():
    data = base64.b64decode(b64)
    p = pathlib.Path(name)
    if p.exists() and p.read_bytes() == data:
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(data)
    changed += 1
    print("written:", name)
print(f"{changed} file(s) changed" if changed else "Already applied. Nothing changed.")
